// Normalize raw teacher input into a consistent shape.
// Source may be a classic webhook body (nested under .body) or an n8n Form
// Trigger submission (fields directly on json, keyed by the fieldLabel text).
// Also carries forward any uploaded file as binary data - Code nodes do not
// forward binary automatically, so it must be re-attached explicitly below.
const item = $input.first();
const body = item.json.body || item.json;
const binary = item.binary || {};

function pick(label) {
  return body[label];
}
function toStr(v) {
  return (v === undefined || v === null) ? '' : String(v).trim();
}
function toInt(v) {
  if (v === undefined || v === null || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? Math.trunc(n) : null;
}

// The uploaded file (if any) is attached as binary data. Its property key is
// whatever the Form Trigger assigned to the "Question Image" field, so it is
// picked up generically here rather than hard-coded, in case the exact key
// differs between n8n versions.
const binaryKeys = Object.keys(binary);
const imageBinaryKey = binaryKeys.length > 0 ? binaryKeys[0] : null;
const hasImage = imageBinaryKey !== null;

const normalized = {
  examName: toStr(pick('Exam Name')),
  academicYear: toStr(pick('Academic Year')) || '2026-27',
  class: toStr(pick('Class')),
  section: toStr(pick('Section')),
  subject: toStr(pick('Subject')),
  examDate: toStr(pick('Exam Date')),
  duration: toStr(pick('Exam Duration')),
  maximumMarks: toInt(pick('Maximum Marks')),
  manualQuestions: toStr(pick('Manual Questions')),
  imageBinaryKey,
  hasImage
};

return [{
  json: { input: normalized },
  binary
}];

// Validates exam-detail fields, and enforces the flexible question-input
// rule: manual questions and the image are each individually optional, but
// at least one of the two must be present.
const item = $input.first();
const input = item.json.input;
const errors = [];

function required(field, label) {
  const v = input[field];
  if (v === null || v === undefined || v === '') {
    errors.push(`${label} is required`);
  }
}

required('examName', 'Exam Name');
required('academicYear', 'Academic Year');
required('class', 'Class');
required('section', 'Section');
required('subject', 'Subject');
required('examDate', 'Exam Date');
required('duration', 'Exam Duration');

if (input.maximumMarks === null || !(input.maximumMarks > 0)) {
  errors.push('Maximum Marks is required and must be greater than zero');
}

const hasManualQuestions = !!(input.manualQuestions && input.manualQuestions.length > 0);
if (!hasManualQuestions && !input.hasImage) {
  errors.push('Provide the questions manually, upload a question image, or both');
}

return [{
  json: {
    input,
    hasManualQuestions,
    validation: {
      stage: 'required_fields',
      valid: errors.length === 0,
      errors
    }
  },
  binary: item.binary || {}
}];

// Builds the clean payload that Workflow 02 expects, and re-attaches the
// uploaded image as binary data (renamed to a fixed "question_image" key so
// Workflow 02 doesn't need to know the original form field's binary key).
// Manual questions are preserved as plain text; the image is preserved as
// binary, never converted into text. Either or both may be present.
const item = $input.first();
const input = item.json.input;
const hasManualQuestions = item.json.hasManualQuestions;
const binary = item.binary || {};

const payload = {
  exam: input.examName,
  academic_year: input.academicYear,
  class: input.class,
  section: input.section,
  subject: input.subject,
  exam_date: input.examDate,
  duration: input.duration,
  max_marks: input.maximumMarks,
  manual_questions: hasManualQuestions ? input.manualQuestions : '',
  has_image: !!input.hasImage
};

const outBinary = {};
if (input.hasImage && input.imageBinaryKey && binary[input.imageBinaryKey]) {
  outBinary.question_image = binary[input.imageBinaryKey];
}

return [{ json: payload, binary: outBinary }];

// Workflow 01 does not know or care about Workflow 02's internal processing
// (OCR, extraction, structuring) - it only checks that Workflow 02 returned
// something usable. Treat any explicit { success: false } or { error } as a
// failure; otherwise treat the call as successful.
const result = $input.first().json;
const failed = result && (result.success === false || result.error);

return [{
  json: {
    wf2Result: result,
    wf2Validation: {
      valid: !failed,
      errors: failed ? [ (result.error && (result.error.message || result.error)) || 'Workflow 2 did not return a successful result' ] : []
    }
  }
}];

// Builds the completion-page content shown to the teacher, summarizing what
// was submitted, plus a download link for each PDF Workflow 03 generated.
const payload = $('Prepare Workflow 2 Payload').first().json;
const documents = ($('Build Final Success Response').first().json.documents) || [];

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const questionSourceParts = [];
if (payload.manual_questions) questionSourceParts.push('typed/pasted questions');
if (payload.has_image) questionSourceParts.push('an uploaded question image');
const questionSource = questionSourceParts.join(' and ');

const downloadLinks = documents.length > 0
  ? '<p><strong>Download your question paper:</strong></p><ul>' +
    documents.map(doc => `<li><a href="${escapeHtml(doc.fileUrl || doc.fileName)}">${escapeHtml(doc.fileName)}</a></li>`).join('') +
    '</ul>'
  : '';

const completionMessage =
  `<p><strong>Exam:</strong> ${escapeHtml(payload.exam)} &nbsp;&nbsp; ` +
  `<strong>Class:</strong> ${escapeHtml(payload.class)}-${escapeHtml(payload.section)} &nbsp;&nbsp; ` +
  `<strong>Subject:</strong> ${escapeHtml(payload.subject)}</p>` +
  `<p><strong>Exam Date:</strong> ${escapeHtml(payload.exam_date)} &nbsp;&nbsp; ` +
  `<strong>Duration:</strong> ${escapeHtml(payload.duration)} &nbsp;&nbsp; ` +
  `<strong>Maximum Marks:</strong> ${escapeHtml(payload.max_marks)}</p>` +
  `<p>Questions received via ${escapeHtml(questionSource)}.</p>` +
  `<p>Your exam has been submitted and the question paper has been generated.</p>` +
  downloadLinks;

return [{
  json: {
    completionTitle: 'Exam Submitted Successfully',
    completionMessage
  }
}];

// Collects errors from whichever validation stage failed and returns a
// single consistent error envelope.
const j = $input.first().json;

let code = 'UNKNOWN_ERROR';
let errors = [];

if (j.validation && j.validation.stage === 'required_fields') {
  code = 'INVALID_INPUT';
  errors = j.validation.errors;
} else if (j.wf3Validation) {
  code = 'DOCUMENT_GENERATION_FAILED';
  errors = j.wf3Validation.errors;
} else if (j.wf2Validation) {
  code = 'QUESTION_ENGINE_FAILED';
  errors = j.wf2Validation.errors;
} else {
  errors = ['An unexpected error occurred in 01_EXAM_CONTROLLER'];
}

return [{
  json: {
    success: false,
    error: {
      code,
      message: errors.join('; ')
    }
  }
}];

// Turns the curated error envelope from Format Error Response into readable
// Form Ending content. Format Error Response already strips this down to a
// { code, message } pair with no internal paths or stack traces - this node
// only wraps that message for display.
const err = $input.first().json; // { success: false, error: { code, message } }
const message = (err && err.error && err.error.message)
  ? err.error.message
  : 'An unexpected error occurred.';

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

return [{
  json: {
    completionTitle: 'Exam Could Not Be Submitted',
    completionMessage: `<p>Your exam could not be submitted.</p><p>${escapeHtml(message)}</p>`
  }
}];

// Wraps the validated Workflow 2 result (the questionPaperData object:
// { success, exam, sets, warnings }) as the single field Workflow 03 expects.
const wf2Result = $json.wf2Result;

return [{
  json: {
    documentInput: wf2Result
  }
}];

// Workflow 01 only checks that Workflow 03 actually produced document(s) -
// it does not inspect PDF content. A result is valid only when Workflow 03
// reported success AND returned at least one document.
const result = $input.first().json;
const failed = !result
  || result.success !== true
  || !Array.isArray(result.documents)
  || result.documents.length === 0;

return [{
  json: {
    wf3Result: result,
    wf3Validation: {
      valid: !failed,
      errors: failed ? [ (result && result.error && (result.error.message || result.error)) || 'Workflow 3 did not return a successful document result' ] : []
    }
  }
}];

// Assembles the final success payload: the teacher's submitted exam
// details plus the PDF document(s) Workflow 03 generated, so the
// completion page can show a download link per set/document.
const payload = $('Prepare Workflow 2 Payload').first().json;
const wf3Result = $('Validate Workflow 3 Result').first().json.wf3Result;
const documents = wf3Result.documents || [];

return [{
  json: {
    success: true,
    exam: payload,
    documents
  }
}];
